def check(self, context: LumiContext, *, confirmed: bool = False) -> None:
    if not self.beta_enabled:
        raise ToolPolicyError("این ابزار در نسخه بتا فعال نیست.")
    if self.requires_auth and not context.authenticated:
        raise ToolAuthenticationRequired("برای استفاده از این ابزار باید وارد حساب شوی.")
    if self.allowed_roles and not (set(context.roles) & set(self.allowed_roles)):
        raise ToolRoleDenied("نقش فعلی اجازه استفاده از این ابزار را ندارد.")
    if self.requires_confirmation and not confirmed:
        raise ToolConfirmationRequired("این عملیات قبل از اجرا به تأیید صریح کاربر نیاز دارد.")

def verify_value(value: str, encoded: str) -> bool:
    try:
        salt_text, digest_text = encoded.split(".", 1)
        salt = _b64d(salt_text)
        expected = _b64d(digest_text)
    except Exception:
        return False
    actual = hashlib.pbkdf2_hmac("sha256", value.encode(), salt, 120_000)
    return hmac.compare_digest(actual, expected)

def record_referral_usage(db: Session, session: VpnSession) -> None:
    # A real usage day requires at least five minutes of VPN time.
    if session.consumed_seconds < 300:
        return
    referral = db.scalar(select(Referral).where(Referral.invited_device_id == session.device_id))
    if not referral:
        return
    # Only first 7 distinct usage days after installation are rewarded.
    if referral.rewarded_days >= 7:
        return
    today = local_date()
    existing = db.scalar(
        select(ReferralDailyReward).where(
            ReferralDailyReward.referral_id == referral.id,
            ReferralDailyReward.local_date == today,
        )
    )
    if existing:
        return
    hearts = int(get_json(db, "referral_daily_hearts", 5))
    reward = ReferralDailyReward(referral_id=referral.id, local_date=today, hearts=hearts)
    db.add(reward)
    if hearts > 0:
        db.add(HeartLedger(user_id=referral.inviter_user_id, amount=hearts, reason="referral_daily_use", reference=f"referral:{referral.id}:{today}"))
    referral.rewarded_days += 1
    # Optional completion bonus on the seventh rewarded day.
    if referral.rewarded_days == 7:
        bonus = int(get_json(db, "referral_day7_bonus_hearts", 5))
        if bonus > 0:
            db.add(HeartLedger(user_id=referral.inviter_user_id, amount=bonus, reason="referral_7day_bonus", reference=f"referral:{referral.id}"))
    try:
        db.commit()
    except IntegrityError:
        db.rollback()

def parse_observation(data,*,price_path,time_path,unit,now=None,max_age_seconds=2400):
    if unit not in ('TOMAN','RIAL'):
        raise FeedError('واحد رسمی سرویس باید به‌صراحت TOMAN یا RIAL تعیین شود.')
    rate=to_decimal(at_path(data,price_path))
    rate=rate/Decimal('10') if unit=='RIAL' else rate
    if rate.as_tuple().exponent < -2:
        raise FeedError('مقدار نرخ بیش از دو رقم اعشار دارد.')
    rate=rate.quantize(Decimal('.01'))
    raw_time=at_path(data,time_path)
    if not isinstance(raw_time,str):
        raise FeedError('زمان ثبت نرخ باید ISO 8601 دارای منطقه زمانی باشد.')
    try:
        observed=datetime.fromisoformat(raw_time.replace('Z','+00:00'))
    except ValueError as exc:
        raise FeedError('زمان ثبت نرخ ISO 8601 معتبر نیست.') from exc
    if observed.tzinfo is None or observed.utcoffset() is None:
        raise FeedError('زمان نرخ باید منطقه زمانی مشخص داشته باشد.')
    now=now or datetime.now(timezone.utc)
    if observed>now+timedelta(minutes=2):
        raise FeedError('زمان نرخ از آینده است.')
    if now-observed>timedelta(seconds=max_age_seconds):
        raise FeedError('زمان نرخ منقضی یا قدیمی است.')
    return Observation(toman_per_gram=rate,observed_at=observed)
